do $$declare missing text;begin select string_agg(name,', ')into missing from(values('friend_close_friends'),('host_follows'),('content_shares'),('message_reactions'),('social_comments'),('social_reports'),('notification_preferences'),('notifications'),('notification_outbox'),('host_announcements'))x(name)where not exists(select 1 from information_schema.tables where table_schema='public'and table_name=x.name);if missing is not null then raise exception 'Missing Stage 6 tables: %',missing;end if;if not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'and p.proname='search_social_profiles_v1')then raise exception 'Secure friend search missing';end if;if not exists(select 1 from pg_policies where schemaname='public'and tablename='messages'and policyname='members read visible messages')then raise exception 'Message authorization missing';end if;if has_table_privilege('authenticated','public.social_comments','INSERT')then raise exception 'Direct comments bypass RPC';end if;end$$;
